  const jEditorCatalog=__CATEGORY_EDITOR_CATALOG__;
  Object.assign(state,{jEditorGroup:'common',jEditorIcon:'coffee',jEditorSub:false});
  function jEditorKind(){return state.page==='flow-transfer-icon'?'transfer':state.dCategoryType==='income'?'income':'expense';}
  function jEditorChoices(){const kind=jEditorKind(),all=jEditorCatalog[kind==='expense'?'expense':'income'];const common=(kind==='expense'?['restaurant','local_cafe','directions_subway','shopping_basket','home','movie','book','favorite','card_giftcard','computer','fitness_center','pets']:['work','account_balance','savings','card_giftcard','paid','trending_up','wallet','emoji_events','handshake','undo','sync','category']);const mapping=new Map(all.flatMap(g=>g.items));return [{label:'常用',items:common.map(k=>[k,mapping.get(k)||'shapes'])},...all];}
  function jEditorGrid(){const groups=jEditorChoices(),active=state.jEditorGroup==='common'?0:Number(state.jEditorGroup)+1,group=groups[active]||groups[0];return `<div class="j-editor-groups">${groups.map((g,i)=>btn('j-editor-group:'+(i?i-1:'common'),g.label,g.label,'v4-chip',`aria-pressed="${g===group}"`)).join('')}</div><div class="j-editor-grid">${group.items.map(([key,i])=>btn('j-editor-icon:'+key,icon(i),'选择'+key+'图标','',`aria-pressed="${state.jEditorIcon===key}" data-icon-key="${key}"`)).join('')}</div>`;}
  function jEditorIconControl(){return `<div class="j-editor-sources">${[['preset','预设图标'],['custom','自定义图标']].map(([v,n])=>btn('j-icon-mode:'+v,n,n,'v4-chip',`aria-pressed="${state.jIconMode===v}"`)).join('')}</div>${state.jIconMode==='preset'?jEditorGrid():`<div class="j-editor-image">${jIconPreview(state.jIconImage,'contain')}<p>保留图片原色与透明背景，选择后裁剪为正方形。</p></div><label class="j-editor-upload">${icon('image-plus')}点击选择图片<input type="file" accept="image/png,image/jpeg,image/webp" data-j-custom-file aria-label="选择自定义图标图片"></label>`}`;}
  function jCategoryEditor(){const key=state.page.replace(/^flow-/,''),creating=key==='category-new',kind=jEditorKind(),sub=creating?state.jEditorSub:!!state.dSub&&kind!=='transfer',name=creating?'':kind==='transfer'?'转账':state.dSub||state.dCategory||'餐饮';if(state.jEditorRoute!==key){state.jEditorRoute=key;state.jEditorIcon=creating?'category':kind==='transfer'?'swap_horiz':'restaurant';state.jEditorGroup=creating?'0':'common';state.jIconMode='preset';if(creating)state.fForm.categoryName='';}return `<div class="j-editor-shell"><div class="j-editor-scroll">${surface(`${fInput('categoryName','分类名称',name,'text','请输入分类名称',true).replace('data-f-field="categoryName"','maxlength="10" data-f-field="categoryName"')}<small class="j-editor-name-count">${fVal('categoryName',name).length}/10</small><div class="j-editor-type">${icon(kind==='transfer'?'arrow-left-right':kind==='expense'?'trending-down':'trending-up')}<span>${kind==='transfer'?'转账':kind==='expense'?'支出分类':'收入分类'}</span></div><div class="j-editor-level"><div><strong>二级分类</strong><small>${sub?'此分类属于某个一级分类':'此分类为独立的一级分类'}</small></div><input class="v4-switch" type="checkbox" role="switch" aria-label="二级分类" data-j-editor-level ${sub?'checked':''} ${creating?'':'disabled'}></div>${sub?btn('j-editor-parent-open',`<span>父分类<small>${esc(fVal('categoryParent','饮品'))}</small></span>${icon('chevron-right')}`,'选择父分类','j-editor-parent-row'):''}`)}${surface(`<h3>分类图标</h3>${jEditorIconControl()}`)}${creating?'':surface(`<button class="j-editor-delete" data-action="f-confirm:删除分类">${icon('trash-2')}<span>删除分类<small>删除后无法恢复</small></span>${icon('chevron-right')}</button>`)}</div><div class="j-editor-footer">${btn('j-save-category','保存','保存分类','bc-primary')}</div></div>`;}
  fDefs['category-edit'].body=jCategoryEditor;
  fDefs['transfer-icon'].body=jCategoryEditor;
  fDefs['transfer-icon'].source='category/category_edit_page.dart';
  fDefine('category-new','新建分类','分类标签与预算','category/category_edit_page.dart',jCategoryEditor);
  let jEditorGroup=[...picker.querySelectorAll('optgroup')].find(g=>g.label==='补齐 · 分类标签与预算');
  if(!jEditorGroup){jEditorGroup=document.createElement('optgroup');jEditorGroup.label='补齐 · 分类标签与预算';picker.appendChild(jEditorGroup);}
  jEditorGroup.appendChild(new Option('新建分类 · 完整图标与父分类','flow-category-new'));
  const jPreviousEditorRender=fRender;
  fRender=function(key){if(!['category-edit','category-new','transfer-icon'].includes(key))return jPreviousEditorRender(key);return `<div class="bc-subhead">${btn('back',icon('chevron-left'),'返回')}<h2>${fDefs[key].title}</h2>${key==='category-new'?'':`<div class="j-editor-tools">${btn('f-go:categoryDetail',icon('chart-pie'),'分类详情')}${btn('f-go:category-migration',icon('arrow-left-right'),'分类迁移')}</div>`}</div>${jCategoryEditor()}`;};
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const [action,arg]=el.dataset.action.split(':');if(!['j-editor-group','j-editor-icon','j-editor-parent-open','j-editor-parent-select'].includes(action))return;e.preventDefault();e.stopImmediatePropagation();if(action==='j-editor-parent-open'){rOpenModal('category-parent-picker');return;}if(action==='j-editor-parent-select'){state.fForm.categoryParent=arg;rDismiss();render();persist();return;}if(action==='j-editor-group')state.jEditorGroup=arg;else{state.jEditorIcon=arg;state.fIcon=jEditorChoices().flatMap(g=>g.items).find(([key])=>key===arg)?.[1]||'shapes';}render();persist();},true);
  root.addEventListener('change',e=>{if(e.target.matches('[data-j-editor-level]')){state.jEditorSub=e.target.checked;render();persist();}},true);

  function jEditorParentBody(){return `<label class="j-editor-parent-search">${icon('search')}<input data-j-parent-query placeholder="搜索分类" aria-label="搜索父分类"></label><div class="j-editor-parent-grid">${pAllCategories.map(([name,i])=>btn('j-editor-parent-select:'+name,`<span class="bc-entry-icon">${jCategoryVisual(name,i)}</span><span>${esc(name)}</span>${name==='购物'?'<small>8 笔</small>':''}`,'选择'+name,'',`${name==='购物'?'disabled':''} aria-pressed="${fVal('categoryParent','饮品')===name}" data-j-parent-name="${name}"`)).join('')}</div>`;}
  const jEditorPreviousModalBody=rModalBody;
  rModalBody=function(key){return key==='category-parent-picker'?jEditorParentBody():jEditorPreviousModalBody(key);};
  Object.assign(rSpecs,{'category-parent-picker':{title:'选择父分类',host:'flow-category-new',kind:'sheet'}});
  fDefine('category-parent-picker','选择父分类','分类标签与预算','category/category_edit_page.dart',jEditorParentBody);
  jEditorGroup.appendChild(new Option('选择父分类 · 图标、笔数与禁用状态','flow-category-parent-picker'));
  root.addEventListener('input',e=>{if(!e.target.matches('[data-j-parent-query]'))return;const query=e.target.value.trim();for(const b of phone.querySelectorAll('[data-j-parent-name]'))b.hidden=!b.dataset.jParentName.includes(query);});

  root.addEventListener('input',e=>{if(e.target.matches('[data-f-field="categoryName"]')){const count=phone.querySelector('.j-editor-name-count');if(count)count.textContent=e.target.value.length+'/10';}});
